<?php

// inicia o GTK
\Gtk::init();

// Cria a classe
class OneFileNotes
{
	private $_config;
	private $_config_file;
	public $saveTimeControl = NULL;

	public $bufferSaveTimeControl = NULL;

	public $widgets;

	public $tabs = [];

	public $svgFile = <<<END

END;

	/**
	 *
	 */
	public function __construct()
	{
		// default config
		$this->_config = [
			'debug' => TRUE,
			'interface' => [
				'showdecoration' => TRUE,
				'width' => 200,
				'height' => 200,
				'x' => 0,
				'y' => 0,
				'alwaysontop' => FALSE
			],
			'sourceview' => [
				'showlinenumbers' => TRUE,
			],
			'source_directory' => ONEFILENOTES_CONFIG_PATH . "/",
		];

		// se o icone não existir, cria
		$iconfile = ONEFILENOTES_CONFIG_PATH . "/OneFileNotes.svg";
		if(!file_exists($iconfile)) {
			file_put_contents($iconfile, base64_decode($this->svgFile));
		}

		// salva a configuração na primeira vez
		$this->_config_file = ONEFILENOTES_CONFIG_PATH . "/config.json";

		if(!file_exists($this->_config_file)) {
			$this->_debug("Salvando primeiras configurações em " . $this->_config_file);

			if(!file_exists(ONEFILENOTES_CONFIG_PATH)) {
				mkdir(ONEFILENOTES_CONFIG_PATH);
			}

			file_put_contents($this->_config_file, json_encode($this->_config));
		}
		else {
			$this->_debug("Lendo configurações de " . $this->_config_file);
			$config = json_decode(file_get_contents($this->_config_file), TRUE);

			$this->_config = $this->_mergeRecursiveDistinct($this->_config, $config);
		}

		// cria a interface
		$this->createInterface();
		
		// mostra tudo
		$this->widgets['wndMain']->show_all();

		// seta o novo tamanho
		$this->widgets['wndMain']->resize($this->_config['interface']['width'], $this->_config['interface']['height']);
		$this->widgets['wndMain']->move($this->_config['interface']['x'], $this->_config['interface']['y']);

		// carrega os arquivos
		$this->loadTabFiles();

		// create and add CSS
		$css_provider = new \GtkCssProvider();
		$css_provider->load_from_data("
			.view.sourceview {
				font-family: Monospace;
				font-size: 9pt;
				font-weight: 100;
			}
		");
		$style_context = new \GtkStyleContext();
		$style_context->add_provider_for_screen($css_provider, 600);

		// inicia o loop
		\Gtk::main();
	}

	/**
	 * cria a interface
	 */
	public function createInterface()
	{
		// cria o form
		$this->widgets['wndMain'] = new \GtkWindow(\Gtk::WINDOW_TOPLEVEL);
		$this->widgets['wndMain']->set_title("OneFileNotes");
		$this->widgets['wndMain']->set_decorated($this->_config['interface']['showdecoration']);
		$this->widgets['wndMain']->set_resizable(TRUE);
		$this->widgets['wndMain']->set_icon_from_file(ONEFILENOTES_CONFIG_PATH . "/OneFileNotes.svg");
		
		// cria o box principal
		$this->widgets['vbxMain'] = new \GtkBox(\GtkOrientation::VERTICAL);
		$this->widgets['vbxMain']->set_border_width(0);
		$this->widgets['wndMain']->add($this->widgets['vbxMain']);
		
		// cria os menus
		$this->createMenu();

		// cria as abas
		$this->widgets['notebook'] = new \GtkNotebook();
		$this->widgets['notebook']->set_scrollable(TRUE);
		$this->widgets['vbxMain']->pack_start($this->widgets['notebook'], TRUE, TRUE, 0);

		// cria os sinais
		$this->widgets['wndMain']->connect("destroy", function($widget) {
			$this->saveConfig();
			\Gtk::main_quit();
		});

		// ao mover
		$this->widgets['wndMain']->connect("configure-event", function($widget, $event) {
			$this->_config['interface']['x'] = $event->configure->x;
			$this->_config['interface']['y'] = $event->configure->y;
			$this->_config['interface']['width'] = $event->configure->width;
			$this->_config['interface']['height'] = $event->configure->height;

			// chama a requisição de um salvamento
			$this->saveConfig();
		});
	}

	/**
	 * cria uma nova aba
	 */
	public function createNewTab($filepath=NULL)
	{
		// se tiver arquivo, le o arquivo
		$name = "new";
		if($filepath != NULL) {
			$filecontent = file_get_contents($filepath);

			// recupera o primeiro # do arquivo, que indica um titulo
			$lines = explode("\n", $filecontent);
			$name = "";
			foreach($lines as $line) {
				// se inicia com #
				if(strpos(trim($line), "#") === 0) {
					$name = $line;
					$name = str_replace("#", "", $name);
					$name = trim($name);
					break;
				}
			}
			
		}

		// eventbox para criação do label e suportar menu de contexto
		$eventbox = new \GtkEventBox();
		$eventbox->add(new \GtkLabel($name));
		$eventbox->show_all();

		// cria as configurações do sourceview
		$this->widgets['sourceLanguageManager'] = new \GtkSourceLanguageManager();
		$lang = $this->widgets['sourceLanguageManager']->get_language("text");

		// cria o buffer
		$sourceBuffer = new \GtkSourceBuffer();
		$sourceBuffer->set_language($lang);

		// cria o sourceview
		$sourceView = \GtkSourceView::new_with_buffer($sourceBuffer);
		$sourceView->set_show_line_numbers($this->_config['sourceview']['showlinenumbers']);
		$sourceView->set_show_line_marks($this->_config['sourceview']['showlinenumbers']);
		$sourceView->set_auto_indent(true);
		$sourceView->set_indent_on_tab(true);
		$sourceView->set_tab_width(4);

		// carrega o ultimo conteudo
		if($filepath != NULL) {
			$sourceBuffer->set_text($filecontent);
		}

		// adiciona o source view ao scrool e no window
		$scroll = new \GtkScrolledWindow();
		$scroll->add($sourceView);

		// adiciona a pagina
		$pagina = $this->widgets['notebook']->append_page($scroll, $eventbox);
		$this->_debug("Pagina " . $pagina . " adicionada");

		// marca como ordenavel
		$this->widgets['notebook']->set_tab_reorderable($scroll, TRUE);


		// reexibe o notebook
		$this->widgets['notebook']->show_all();
		$this->widgets['notebook']->set_current_page($pagina);

		// adiciona o tab ao vetor
		$this->tabs[] = [
			'name' => $name,
			'filename' => $filepath,
			'sourceview' => $sourceView,
			'tab_label' => $eventbox
		];

		// conecta ao changed
		$sourceBuffer->connect("changed", function($buffer) use ($sourceView) {
			// se ja tiver nada esperando, cancela
			if($this->bufferSaveTimeControl != NULL) {
				\Gtk::source_remove($this->bufferSaveTimeControl);
			}

			// cria uma nova
			$this->bufferSaveTimeControl = \Gtk::timeout_add(1000, function() use ($buffer, $sourceView) {

				// 
				$this->_debug("ACABOU DE DIGITAR!");

				// recupera o texto
				$text = $buffer->get_text($buffer->get_start_iter(), $buffer->get_end_iter(), FALSE);
				
				// recupera o primeiro # do arquivo, que indica um titulo
				$lines = explode("\n", $text);
				$name = "";
				foreach($lines as $line) {
					// se inicia com #
					if(strpos(trim($line), "#") === 0) {
						$name = $line;
						$name = str_replace("#", "", $name);
						$name = trim($name);
						break;
					}
				}

				// recupera o tab
				foreach($this->tabs as $index => $tab) {
					
					if($tab['sourceview'] === $sourceView) {
						
						// seta o nome caso tenha achado
						if($tab['name'] != $name) {
							// cria o nome do novo arquivo e verifica se ele ja existe
							$filename = $this->_config['source_directory'] . "/" . $name . ".md";
							$this->_debug("ARQUIVO: " . $filename);
							if(file_exists($filename)) {
								$name = $name . "_0";
							}

							// recria o novo nome
							$filename = $this->_config['source_directory'] . "/" . $name . ".md";
							$this->_debug("ARQUIVO: " . $filename);
							if(!file_exists($filename)) {

								// se o arquivo ja ta salvo, renomeia
								if(strlen($this->tabs[$index]['filename']??"") > 0) {
									rename($this->tabs[$index]['filename'], $filename);
								}

								$this->tabs[$index]['filename'] = $filename;
							}

							// muda o nome, o tab
							$this->tabs[$index]['name'] = $name;
							$this->tabs[$index]['tab_label']->get_children()[0]->set_label($name);
						}

						break;
					}
				}

				// se tiver nome do arquivo, salva
				if($this->tabs[$index]['filename'] !== NULL) {
					file_put_contents($this->tabs[$index]['filename'], $text);
					$this->_debug("ARQUIVO " . $this->tabs[$index]['filename'] . " SALVO!");
				}
				
				// finaliza o temporizador
				$this->bufferSaveTimeControl = NULL;
				return FALSE;
			});
		});

		// adiciona o evento ao eventbox
		$eventbox->connect("button-release-event", function($widget, $event) use ($scroll) {
	
			// right click
			if($event->button->button == 3) {

				// recupera a pagina
				$pagina = $this->widgets['notebook']->page_num($scroll);
	
				// cria o menu
				$menu = new \GtkMenu();
				$menu->append($mnuClose=\GtkMenuItem::new_with_label("Fechar"));
				$menu->show_all();

				// menu fechar
				$mnuClose->connect("activate", function() use ($pagina) {

					// pergunta se deve remover o arquivo
					$dialog = \GtkMessageDialog::new_with_markup($this->widgets['wndMain'], \GtkDialogFlags::MODAL, \GtkMessageType::WARNING, \GtkButtonsType::OK_CANCEL, "when close a tab, the file will be deleted too!");
					$result = $dialog->run();
					if($result != \GtkResponseType::CANCEL) {

						// percorre as tabs
						foreach($this->tabs as $index => $tab) {

							// recupera a pagina
							$sourceView = $tab['sourceview'];
							$scroll = $sourceView->get_parent();
							$page = $this->widgets['notebook']->page_num($scroll);

							// verifica se é a pagina
							if($pagina == $page) {
								// remove o arquivo
								unlink($tab['filename']);

								// remove a tab
								$this->widgets['notebook']->remove_page($pagina);

								// remove do global
								unset($this->tabs[$index]);

								// ja sai
								break;
							}

						}

						// recupera a pagina
				// $pagina = $this->widgets['notebook']->page_num($scroll);

						// recupra o tab
						// $this->widgets['notebook']->get_action_widget($pagina);

						// $this->widgets['notebook']->remove_page($pagina);


					}
					$dialog->destroy();
				});
				
				// mostra o menu
				$menu->popup_at_pointer($event);
			}
	
		});
	}

	/**
	 * carrega os arquivos nas abas
	 */
	public function loadTabFiles()
	{
		// remove as abas
		$pages = $this->widgets['notebook']->get_n_pages() - 1;
		for($i=$pages; $i>=0; $i--) {
			$this->widgets['notebook']->remove_page($i);
		}

		// faz o loop nos arquivos do diretório
		$files = scandir($this->_config['source_directory']);
		foreach($files as $file) {
			// verifica se o arquivo é um .md
			$extension = pathinfo($file, PATHINFO_EXTENSION);
			if($extension == "md") {
				$this->createNewTab($this->_config['source_directory'] . "/" . $file);
			}
		}
	}

	/**
	 * função que chama o salvamento das configurações
	 */
	public function saveConfig()
	{
		// se ja tiver nada esperando, cancela
		if($this->saveTimeControl != NULL) {
			\Gtk::source_remove($this->saveTimeControl);
		}

		// cria uma nova
		$this->saveTimeControl = \Gtk::timeout_add(1000, function() {

			// salva o arquivo
			file_put_contents($this->_config_file, json_encode($this->_config));

			//
			$this->_debug("SALVOU!");

			// finaliza o temporizador
			$this->saveTimeControl = NULL;
			return FALSE;
		});
	}

	/**
	 * cria os menus
	 */
	public function createMenu()
	{

		// cria a barra de menu
		$menubar = new \GtkMenuBar();
		$this->widgets['vbxMain']->pack_start($menubar, FALSE, FALSE, 0);


			// arquivo
			$mnuFile = \GtkMenuItem::new_with_label("File");
			$menubar->append($mnuFile);
			$menu = new \GtkMenu();

				// new file
				$this->widgets['mnuNewFile'] = \GtkMenuItem::new_with_label("New file");
				$menu->append($this->widgets['mnuNewFile']);
				
				// --
				$menu->append(new \GtkSeparatorMenuItem());

				// exit
				$this->widgets['mnuExit'] = \GtkMenuItem::new_with_label("Exit");
				$menu->append($this->widgets['mnuExit']);

				$mnuFile->set_submenu($menu);

			// view
			$mnuView = \GtkMenuItem::new_with_label("View");
			$menubar->append($mnuView);
			$menu = new \GtkMenu();

				// seta o diretório para salvar os arquivos
				$this->widgets['mnuShowLineNumbers'] = \GtkCheckMenuItem::new_with_label("Show Line Numbers");
				$menu->append($this->widgets['mnuShowLineNumbers']);

				$mnuView->set_submenu($menu);

			// preferencias
			$mnuPreferences = \GtkMenuItem::new_with_label("Preferences");
			$menubar->append($mnuPreferences);
			$menu = new \GtkMenu();

				// seta o diretório para salvar os arquivos
				$this->widgets['mnuSetDirectory'] = \GtkMenuItem::new_with_label("Set directory to save files");
				$menu->append($this->widgets['mnuSetDirectory']);

				// mostra ou não a decoração das janelas
				$this->widgets['mnuShowDecoration'] = \GtkCheckMenuItem::new_with_label("Window Decoration");
				$menu->append($this->widgets['mnuShowDecoration']);

				// deixa sempre no topo ou não
				$this->widgets['mnuAlwaysOnTop'] = \GtkCheckMenuItem::new_with_label("Always On Top");
				$menu->append($this->widgets['mnuAlwaysOnTop']);

				// debug interativo
				$this->widgets['mnuInteractiveDebug'] = \GtkMenuItem::new_with_label("Open Interactive Debugging");
				$menu->append($this->widgets['mnuInteractiveDebug']);

				// criar link
				$desktop_file = "/home/" . getenv("USER") . "/.local/share/applications/OneFileNotes.desktop";
				if(file_exists($desktop_file)) {
					$this->widgets['mnuCreateMenu'] = \GtkMenuItem::new_with_label("Remove .desktop menu");	
				}
				else {
					$this->widgets['mnuCreateMenu'] = \GtkMenuItem::new_with_label("Create .desktop menu");
				}
				$menu->append($this->widgets['mnuCreateMenu']);

				// iniciar automaticamente
				$this->widgets['mnuAutoStart'] = \GtkCheckMenuItem::new_with_label("Auto Start");
				$menu->append($this->widgets['mnuAutoStart']);

				$mnuPreferences->set_submenu($menu);

		// exit
		$this->widgets['mnuExit']->connect("activate", function($widget) {
			\Gtk::main_quit();
		});

		// novo arquivo
		$this->widgets['mnuNewFile']->connect("activate", function($widget) {
			$this->createNewTab();
		});

		
		// seta o diretório onde os arquivos serão salvos
		$this->widgets['mnuSetDirectory']->connect("activate", function($widget) {
			// configure file selection 
			$dialog = new \GtkFileChooserDialog("Choose a directory", $this->widgets['wndMain'], \GtkFileChooserAction::SELECT_FOLDER, ["Cancel", \GtkResponseType::CANCEL, "Ok", \GtkResponseType::OK]);
			$dialog->set_current_folder($this->_config['source_directory']);
			$result = $dialog->run();
			if($result == \GtkResponseType::OK) {
				$dir = $dialog->get_filenames()[0];
				if(is_dir($dir)) {
					$this->_config['source_directory'] = $dir;

					// salva a nova configuração
					$this->saveConfig();

					// recarrega os tabs
					$this->loadTabFiles();
				}
			}
			$dialog->destroy();
		});
	
		// mostrar a decoração da janela
		if($this->_config['interface']['showdecoration']) {
			$this->widgets['mnuShowDecoration']->set_active(TRUE);
		}
		$this->widgets['mnuShowDecoration']->connect("activate", function($widget) {
			$this->_config['interface']['showdecoration'] = FALSE;
			if($widget->get_active()) {
				$this->_config['interface']['showdecoration'] = TRUE;
				
			}
			$this->widgets['wndMain']->set_decorated($this->_config['interface']['showdecoration']);

			// salva a configuração
			$this->saveConfig();
		});
	
		// mostrar as linhas
		if($this->_config['sourceview']['showlinenumbers']) {
			$this->widgets['mnuShowLineNumbers']->set_active(TRUE);
		}
		$this->widgets['mnuShowLineNumbers']->connect("activate", function($widget) {
			// percorre os sourcesview
			foreach($this->tabs as $tab) {

				$sourceView = $tab['sourceview'];

				$this->_config['sourceview']['showlinenumbers'] = FALSE;
				if($widget->get_active()) {
					$this->_config['sourceview']['showlinenumbers'] = TRUE;	
				}

				$sourceView->set_show_line_numbers($this->_config['sourceview']['showlinenumbers']);
				$sourceView->set_show_line_marks($this->_config['sourceview']['showlinenumbers']);
				
			}

			// salva a configuração
			$this->saveConfig();
		});

		// always on top
		if($this->_config['interface']['alwaysontop']) {
			$this->widgets['mnuAlwaysOnTop']->set_active(TRUE);
			$this->widgets['wndMain']->set_keep_above(TRUE);
		}
		$this->widgets['mnuAlwaysOnTop']->connect("activate", function($widget) {

			if($widget->get_active()) {
				$this->_config['interface']['alwaysontop'] = TRUE;
				$this->widgets['wndMain']->set_keep_above(TRUE);
			}
			else {
				$this->_config['interface']['alwaysontop'] = FALSE;
				$this->widgets['wndMain']->set_keep_above(FALSE);
			}

			// salva a configuração
			$this->saveConfig();

		});

		// interactive debug
		$this->widgets['mnuInteractiveDebug']->connect("activate", function($widget) {
			$this->widgets['wndMain']->set_interactive_debugging(TRUE);
		});

		// create .desktop menu 
		$this->widgets['mnuCreateMenu']->connect("activate", function($widget) {

			// cria o caminho do arquivo
			$desktop_file = "/home/" . getenv("USER") . "/.local/share/applications/OneFileNotes.desktop";
			if(file_exists($desktop_file)) {
				unlink($desktop_file);

				// muda o nome do menu
				$this->widgets['mnuCreateMenu']->set_label("Create .desktop menu");
			}
			else {
				// recupera o comando executa
				$pid = getmypid();
				$cmdline = file_get_contents("/proc/$pid/cmdline");
				$cmdline = str_replace("\0", " ", trim($cmdline));

				// cria o arquivo .desktop
				file_put_contents($desktop_file, "[Desktop Entry]
Name=OneFileNotes
Icon=" . ONEFILENOTES_CONFIG_PATH . "/OneFileNotes.svg
Exec=" . $cmdline . "
Type=Application
Comment=OneFileNotes
Categories=Office;");

				// muda o nome do menu
				$this->widgets['mnuCreateMenu']->set_label("Remove .desktop menu");
			}
		});

		// auto iniciar com as sesão do usuario
		$autostart_file = "/home/" . getenv("USER") . "/.config/autostart/OneFileNotes.desktop";
		if(file_exists($autostart_file)) {
			$this->widgets['mnuAutoStart']->set_active(TRUE);
		}
		$this->widgets['mnuAutoStart']->connect("activate", function($widget) {

			// cria o caminho do arquivo
			$autostart_file = "/home/" . getenv("USER") . "/.config/autostart/OneFileNotes.desktop";
			if($widget->get_active()) {

				// recupera o comando executa
				$pid = getmypid();
				$cmdline = file_get_contents("/proc/$pid/cmdline");
				$cmdline = str_replace("\0", " ", trim($cmdline));

				// cria o arquivo .desktop
				file_put_contents($autostart_file, "[Desktop Entry]
Type=Application
Name=OneFileNotes
Type=Application
Hidden=false
NoDisplay=false
Icon=" . ONEFILENOTES_CONFIG_PATH . "/OneFileNotes.svg
Comment=OneFileNotes
Exec=" . $cmdline);
			}
			else {
				unlink($autostart_file);
			}
		});
			
	}

	/**
	 * debuga mensagens no console
	 */
	private function _debug($msg)
	{
		if($this->_config['debug']) {
			echo "DEBUG: " . $msg . "\n";
		}
	}

	/**
	 * faz o merge recursivo para novas configurações
	 */
	private function _mergeRecursiveDistinct($array1, $array2)
	{
		$merged = $array1;

		foreach($array2 as $key => $value) {
			if(is_array($value) && isset($merged[$key]) && is_array($merged[$key])) {
				$merged[$key] = $this->_mergeRecursiveDistinct($merged[$key], $value);
			}
			else {
				$merged[$key] = $value;
			}
		}

		return $merged;
	}


}

